/* Vintage Paper Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="vintage-paper-light"] {
  --background: hsl(43.98 54.82% 92.92%);
  --foreground: hsl(28.51 14.43% 25.41%);
  --card: hsl(42 92.47% 97.83%);
  --card-foreground: hsl(28.51 14.43% 25.41%);
  --popover: hsl(42 92.47% 97.83%);
  --popover-foreground: hsl(28.51 14.43% 25.41%);
  --primary: hsl(30.05 34.88% 48.7%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(40.65 33.43% 81.98%);
  --secondary-foreground: hsl(28.97 18.79% 30.25%);
  --muted: hsl(39 34.58% 88.05%);
  --muted-foreground: hsl(32.33 19.12% 41.39%);
  --accent: hsl(42.86 30.32% 74.55%);
  --accent-foreground: hsl(28.51 14.43% 25.41%);
  --destructive: hsl(9.9 52.71% 46.33%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(40 29.5% 79.51%);
  --input: hsl(40 29.5% 79.51%);
  --ring: hsl(30.05 34.88% 48.7%);
  --chart-1: hsl(30.05 34.88% 48.7%);
  --chart-2: hsl(31.32 28.67% 42.66%);
  --chart-3: hsl(33.77 34.6% 34.22%);
  --chart-4: hsl(29.08 29.98% 57.28%);
  --chart-5: hsl(30.02 35.15% 63.07%);
  --radius: 0.25rem;
  --sidebar: hsl(39 34.58% 88.05%);
  --sidebar-foreground: hsl(28.51 14.43% 25.41%);
  --sidebar-primary: hsl(30.05 34.88% 48.7%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(42.86 30.32% 74.55%);
  --sidebar-accent-foreground: hsl(28.51 14.43% 25.41%);
  --sidebar-border: hsl(40 29.5% 79.51%);
  --sidebar-ring: hsl(30.05 34.88% 48.7%);
  --font-sans: Libre Baskerville, serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: hsl(28 13% 20%);
  --shadow-opacity: 0.12;
  --shadow-blur: 5px;
  --shadow-spread: 0px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-sm:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 1px 2px -1px hsl(28 13% 20% / 0.12);
  --shadow:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 1px 2px -1px hsl(28 13% 20% / 0.12);
  --shadow-md:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 2px 4px -1px hsl(28 13% 20% / 0.12);
  --shadow-lg:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 4px 6px -1px hsl(28 13% 20% / 0.12);
  --shadow-xl:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 8px 10px -1px hsl(28 13% 20% / 0.12);
  --shadow-2xl: 2px 3px 5px 0px hsl(28 13% 20% / 0.3);
  --tracking-normal: 0em;
}

